/* ---- logic.js ---- */
// Pure application logic (no DOM). Covers FR-01, FR-02, QR-02 and login validation.

const DURATION_BUCKETS = [
  { id: "any", label: "Any duration", test: () => true },
  { id: "le30", label: "Up to 30 minutes", test: m => m <= 30 },
  { id: "31-45", label: "31 to 45 minutes", test: m => m > 30 && m <= 45 },
  { id: "46-60", label: "46 to 60 minutes", test: m => m > 45 && m <= 60 },
  { id: "gt60", label: "Over 60 minutes", test: m => m > 60 },
];

const MAX_ACTIVITY_BYTES = 1024 * 1024; // A3: saved activity payload <= 1 MB

/** criteria: { level, topic, duration, material } where "" or "any" means no filter. */
function filterActivities(list, criteria = {}) {
  const { level = "", topic = "", duration = "any", material = "" } = criteria;
  const bucket = DURATION_BUCKETS.find(b => b.id === duration) || DURATION_BUCKETS[0];
  return list.filter(a =>
    (!level || a.level === level) &&
    (!topic || a.topic === topic) &&
    bucket.test(a.minutes) &&
    (!material || a.materials.includes(material))
  );
}

/** FR-02: instructions, materials, cost and safety must all be present. */
function isCompleteActivity(a) {
  return !!a && typeof a.title === "string" && a.title.trim() !== "" &&
    Array.isArray(a.steps) && a.steps.length > 0 && a.steps.every(s => String(s).trim() !== "") &&
    Array.isArray(a.materials) && a.materials.length > 0 &&
    typeof a.costNAD === "number" && a.costNAD >= 0 &&
    typeof a.safety === "string" && a.safety.trim() !== "";
}

function formatCost(n) {
  return n === 0 ? "No cost (free or found materials)" : "About N$ " + n;
}

function payloadBytes(obj) {
  return new TextEncoder().encode(JSON.stringify(obj)).length;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Returns { valid, errors: { email?, password? } } with plain-language messages. */
function validateLogin({ email = "", password = "" } = {}) {
  const errors = {};
  if (!email.trim()) errors.email = "Enter your email address.";
  else if (!EMAIL_RE.test(email.trim())) errors.email = "Enter an email address like name@example.org.";
  if (!password) errors.password = "Enter your password.";
  else if (password.length < 8) errors.password = "Your password must be at least 8 characters.";
  return { valid: Object.keys(errors).length === 0, errors };
}

function describeFilters(criteria) {
  const parts = [];
  if (criteria.level) parts.push("Level: " + criteria.level);
  if (criteria.topic) parts.push("Topic: " + criteria.topic);
  if (criteria.duration && criteria.duration !== "any") {
    parts.push("Duration: " + DURATION_BUCKETS.find(b => b.id === criteria.duration).label);
  }
  if (criteria.material) parts.push("Materials: " + criteria.material);
  return parts;
}


/* ---- storage.js ---- */
// Saved-activity store (FR-03). Storage is injected so tests can use a fake.
// This is the interface-side adapter; the backend task can replace it behind the same methods.

class StorageFullError extends Error { constructor(m) { super(m); this.name = "StorageFullError"; } }
class PayloadTooLargeError extends Error { constructor(m) { super(m); this.name = "PayloadTooLargeError"; } }
class IncompleteActivityError extends Error { constructor(m) { super(m); this.name = "IncompleteActivityError"; } }

const key = userId => "stemmate.saved.v1." + userId;
const backupKey = userId => "stemmate.saved.v1.corrupt-backup." + userId;

function isQuotaError(e) {
  return !!e && (e.name === "QuotaExceededError" || e.name === "NS_ERROR_DOM_QUOTA_REACHED" || e.code === 22 || e.code === 1014);
}

function createSavedStore(storage) {
  function read(userId) {
    const raw = storage.getItem(key(userId));
    if (raw == null) return [];
    try {
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) throw new Error("not an array");
      return parsed;
    } catch {
      // Recovery: keep the unreadable text aside, start with an empty list instead of crashing.
      try { storage.setItem(backupKey(userId), raw); } catch { /* ignore */ }
      try { storage.removeItem(key(userId)); } catch { /* ignore */ }
      return [];
    }
  }
  return {
    list: userId => read(userId),
    get: (userId, id) => read(userId).find(a => a.id === id) || null,
    isSaved: (userId, id) => read(userId).some(a => a.id === id),
    save(userId, activity) {
      if (!isCompleteActivity(activity)) throw new IncompleteActivityError("This activity is missing instructions, materials, cost or safety notes, so it cannot be saved.");
      if (payloadBytes(activity) > MAX_ACTIVITY_BYTES) throw new PayloadTooLargeError("This activity is larger than 1 MB.");
      const items = read(userId).filter(a => a.id !== activity.id); // replace, never duplicate
      items.push({ ...activity, savedAt: new Date().toISOString() });
      try {
        storage.setItem(key(userId), JSON.stringify(items));
      } catch (e) {
        if (isQuotaError(e)) throw new StorageFullError("There is not enough space on this device to save the activity.");
        throw e;
      }
      return items.length;
    },
    remove(userId, id) {
      const items = read(userId).filter(a => a.id !== id);
      storage.setItem(key(userId), JSON.stringify(items));
      return items.length;
    },
  };
}


/* ---- auth.js ---- */
// PLACEHOLDER auth (SR-01): compares against synthetic demo accounts and keeps the session in
// sessionStorage so each browser session needs a fresh login (A3 decision for shared devices).
// The backend login (team task 10) should replace verify() while keeping this interface.

class AuthError extends Error { constructor(m, errors) { super(m); this.name = "AuthError"; this.errors = errors || {}; } }

const SESSION_KEY = "stemmate.session";

function createAuth(sessionStorageLike, accounts) {
  return {
    login(email, password) {
      const v = validateLogin({ email, password });
      if (!v.valid) throw new AuthError("Please fix the highlighted fields.", v.errors);
      const acc = accounts.find(a => a.email.toLowerCase() === email.trim().toLowerCase() && a.password === password);
      if (!acc) throw new AuthError("Email or password is not correct. Check them and try again.", {});
      const user = { id: acc.id, name: acc.name };
      sessionStorageLike.setItem(SESSION_KEY, JSON.stringify(user));
      return user;
    },
    currentUser() {
      try { return JSON.parse(sessionStorageLike.getItem(SESSION_KEY)); } catch { return null; }
    },
    logout() { sessionStorageLike.removeItem(SESSION_KEY); },
  };
}


